window.BOOK={"key":"taiyyaqadar","app":"mutoon-taiyyaqadar","lsk":"mutoon_taiyyaqadar_v1","prefix":"ta_","title":"تائية ابن تيمية في القدر","sub":"العقيدة · شيخ الإسلام ابن تيمية (ت ٧٢٨هـ) · ١٣٣ بيتًا","poems":[{"id":"taiyyaqadar","title":"تائية ابن تيمية في القدر","nazim":"تقي الدين أحمد بن عبد الحليم ابن تيمية","death":"ت ٧٢٨هـ","meter":"الطويل","source":"المكتبة الشاملة: القصيدة التائية في القدر، شرح وتحقيق محمد بن إبراهيم الحمد","srcUrl":"https://ketabonline.com/ar/books/7162","note":"النص المحقق (على ست نسخ) من «شرح التائية في القدر» لمحمد بن إبراهيم الحمد: أبيات سؤال الذمي الثمانية ثم الجواب ١٢٥ بيتًا، قوبل كلمةً كلمةً بسكربت بنشرة المحقق المفردة في الشاملة وبنص «الدرة البهية» للسعدي وبنص «مجموع الفتاوى» (ويكي مصدر). لم توجد نسخة مشكولة شكلًا تامًا (النشرة مشكولة نحو ١٥٪)، فأكمل الذكاء الاصطناعي الشكل على حركات النشرة والوزن، وكل شطر موزون على الطويل، ويحسن مراجعته على المطبوع.","verses":[["أَيَا عُلَمَاءَ الدِّينِ ذِمِّيُّ دِينِكُمْ","تَحَيَّرَ دُلُّوهُ بِأَوْضَحِ حُجَّةِ"],["إِذَا مَا قَضَى رَبِّي بِكُفْرِي بِزَعْمِكُمْ","وَلَمْ يَرْضَهُ مِنِّي فَمَا وَجْهُ حِيلَتِي"],["دَعَانِي وَسَدَّ الْبَابَ عَنِّي فَهَلْ إِلَى","دُخُولِي سَبِيلٌ بَيِّنُوا لِي قَضِيَّتِي"],["قَضَى بِضَلَالِي ثُمَّ قَالَ ارْضَ بِالْقَضَا","فَمَا أَنَا رَاضٍ بِالَّذِي فِيهِ شِقْوَتِي"],["فَإِنْ كُنْتُ بِالْمَقْضِيِّ يَا قَوْمُ رَاضِيًا","فَرَبِّيَ لَا يَرْضَى بِشُؤْمِ بَلِيَّتِي"],["وَهَلْ لِي رِضَا مَا لَيْسَ يَرْضَاهُ سَيِّدِي","فَقَدْ حِرْتُ دُلُّونِي عَلَى كَشْفِ حَيْرَتِي"],["إِذَا شَاءَ رَبِّي الْكُفْرَ مِنِّي مَشِيئَةً","فَهَلْ أَنَا عَاصٍ فِي اتِّبَاعِ الْمَشِيئَةِ"],["وَهَلْ لِي اخْتِيَارٌ أَنْ أُخَالِفَ حُكْمَهُ","فَبِاللَّهِ فَاشْفُوا بِالْبَرَاهِينِ غُلَّتِي"],["سُؤَالُكَ يَا هَذَا سُؤَالُ مُعَانِدٍ","مُخَاصِمِ رَبِّ الْعَرْشِ بَارِي الْبَرِيَّةِ"],["فَهَذَا سُؤَالٌ خَاصَمَ الْمَلَأَ الْعُلَى","قَدِيمًا بِهِ إِبْلِيسُ أَصْلُ الْبَلِيَّةِ"],["وَمَنْ يَكُ خَصْمًا لِلْمُهَيْمِنِ يَرْجِعَنْ","عَلَى أُمِّ رَأْسٍ هَاوِيًا فِي الْحُفَيْرَةِ"],["وَيُدْعَى خُصُومُ اللَّهِ يَوْمَ مَعَادِهِمْ","إِلَى النَّارِ طُرًّا مَعْشَرَ الْقَدَرِيَّةِ"],["سَوَاءٌ نَفَوْهُ أَوْ سَعَوْا لِيُخَاصِمُوا","بِهِ اللَّهَ أَوْ مَارَوْا بِهِ لِلشَّرِيعَةِ"],["وَأَصْلُ ضَلَالِ الْخَلْقِ مِنْ كُلِّ فِرْقَةٍ","هُوَ الْخَوْضُ فِي فِعْلِ الْإِلَهِ بِعِلَّةِ"],["فَإِنَّهُمُ لَمْ يَفْهَمُوا حِكْمَةً لَهُ","فَصَارُوا عَلَى نَوْعٍ مِنَ الْجَاهِلِيَّةِ"],["فَإِنَّ جَمِيعَ الْكَوْنِ أَوْجَبَ فِعْلَهُ","مَشِيئَةُ رَبِّ الْخَلْقِ بَارِي الْخَلِيقَةِ"],["وَذَاتُ إِلَهِ الْخَلْقِ وَاجِبَةٌ بِمَا","لَهَا مِنْ صِفَاتٍ وَاجِبَاتٍ قَدِيمَةِ"],["مَشِيئَتُهُ مَعْ عِلْمِهِ ثُمَّ قُدْرَةٌ","لَوَازِمُ ذَاتِ اللَّهِ قَاضِي الْقَضِيَّةِ"],["وَإِبْدَاعُهُ مَا شَاءَ مِنْ مُبْدَعَاتِهِ","بِهَا حِكْمَةٌ فِيهِ وَأَنْوَاعُ رَحْمَةِ"],["وَلَسْنَا إِذَا قُلْنَا جَرَتْ بِمَشِيئَةٍ","مِنَ الْمُنْكِرِي آيَاتِهِ الْمُسْتَقِيمَةِ"],["بَلِ الْحَقُّ أَنَّ الْحُكْمَ لِلَّهِ وَحْدَهُ","لَهُ الْخَلْقُ وَالْأَمْرُ الَّذِي فِي الشَّرِيعَةِ"],["هُوَ الْمَلِكُ الْمَحْمُودُ فِي كُلِّ حَالَةٍ","لَهُ الْمُلْكُ مِنْ غَيْرِ انْتِقَاصٍ بِشِرْكَةِ"],["فَمَا شَاءَ مَوْلَانَا الْإِلَهُ فَإِنَّهُ","يَكُونُ وَمَا لَا لَا يَكُونُ بِحِيلَةِ"],["وَقُدْرَتُهُ لَا نَقْصَ فِيهَا وَحُكْمُهُ","يَعُمُّ فَلَا تَخْصِيصَ فِي ذِي الْقَضِيَّةِ"],["أُرِيدُ بِذَا أَنَّ الْحَوَادِثَ كُلَّهَا","بِقُدْرَتِهِ كَانَتْ وَمَحْضِ الْمَشِيئَةِ"],["وَمَالِكُنَا فِي كُلِّ مَا قَدْ أَرَادَهُ","لَهُ الْحَمْدُ حَمْدًا يَعْتَلِي كُلَّ مِدْحَةِ"],["فَإِنَّ لَهُ فِي الْخَلْقِ مِنْ نِعَمٍ سَرَتْ","وَمِنْ حِكَمٍ فَوْقَ الْعُقُولِ الْحَكِيمَةِ"],["أُمُورًا يَحَارُ الْعَقْلُ فِيهَا إِذَا رَأَى","مِنَ الْحِكَمِ الْعُلْيَا وَكُلِّ عَجِيبَةِ"],["فَنُؤْمِنُ أَنَّ اللَّهَ عَزَّ بِقُدْرَةٍ","وَخَلْقٍ وَإِبْرَامٍ لِحُكْمِ الْمَشِيئَةِ"],["فَنُثْبِتُ هَذَا كُلَّهُ لِإِلَهِنَا","وَنُثْبِتُ مَا فِي ذَاكَ مِنْ كُلِّ حِكْمَةِ"],["وَهَذَا مَقَامٌ طَالَمَا عَجَزَ الْأُلَى","نَفَوْهُ وَكَرُّوا رَاجِعِينَ بِحَيْرَةِ"],["وَتَحْقِيقُ مَا فِيهِ بِتَبْيِينِ غَوْرِهِ","وَتَحْرِيرُ حَقِّ الْحَقِّ فِي ذِي الْحَقِيقَةِ"],["هُوَ الْمَطْلَبُ الْأَقْصَى لِوُرَّادِ بَحْرِهِ","وَذَا عَسِرٌ فِي نَظْمِ هَذِي الْقَصِيدَةِ"],["لِحَاجَتِهِ تَبْيِينَ عِلْمٍ مُحَقَّقٍ","لِأَوْصَافِ مَوْلَانَا الْإِلَهِ الْكَرِيمَةِ"],["وَأَسْمَائِهِ الْحُسْنَى وَأَحْكَامِ دِينِهِ","وَأَفْعَالِهِ فِي كُلِّ هَذِي الْخَلِيقَةِ"],["وَهَذَا بِحَمْدِ اللَّهِ قَدْ بَانَ ظَاهِرًا","وَإِلْهَامُهُ لِلْخَلْقِ أَفْضَلُ نِعْمَةِ"],["وَقَدْ قِيلَ فِي هَذَا وَخُطَّ كِتَابُهُ","بَيَانٌ شِفَاءٌ لِلنُّفُوسِ الْمَرِيضَةِ"],["فَقَوْلُكَ لِمْ قَدْ شَاءَ مِثْلُ سُؤَالِ مَنْ","يَقُولُ فَلِمْ قَدْ كَانَ فِي الْأَزَلِيَّةِ"],["وَذَاكَ سُؤَالٌ يُبْطِلُ الْعَقْلُ وَجْهَهُ","وَتَحْرِيمُهُ قَدْ جَاءَ فِي كُلِّ شِرْعَةِ"],["وَفِي الْكَوْنِ تَخْصِيصٌ كَثِيرٌ يَدُلُّ مَنْ","لَهُ نَوْعُ عَقْلٍ أَنَّهُ بِإِرَادَةِ"],["وَإِصْدَارُهُ عَنْ وَاحِدٍ بَعْدَ وَاحِدٍ","أَوِ الْقَوْلُ بِالتَّجْوِيزِ رَمْيَةُ حَيْرَةِ"],["وَلَا رَيْبَ فِي تَعْلِيقِ كُلِّ مُسَبَّبٍ","بِمَا قَبْلَهُ مِنْ عِلَّةٍ مُوجِبِيَّةِ"],["بَلِ الشَّأْنُ فِي الْأَسْبَابِ أَسْبَابِ مَا تَرَى","وَإِصْدَارِهَا عَنْ حُكْمِ مَحْضِ الْمَشِيئَةِ"],["وَقَوْلُكَ لِمْ شَاءَ الْإِلَهُ هُوَ الَّذِي","أَزَلَّ عُقُولَ الْخَلْقِ فِي قَعْرِ حُفْرَةِ"],["فَإِنَّ الْمَجُوسَ الْقَائِلِينَ بِخَالِقٍ","لِنَفْعٍ وَرَبٍّ مُبْدِعٍ لِلْمَضَرَّةِ"],["سُؤَالُهُمُ عَنْ عِلَّةِ السِّرِّ أَوْقَعَتْ","أَوَائِلَهُمْ فِي شُبْهَةِ الثَّنَوِيَّةِ"],["وَأَنَّ مَلَاحِيدَ الْفَلَاسِفَةِ الْأُلَى","يَقُولُونَ بِالْفِعْلِ الْقَدِيمِ بِعِلَّةِ"],["بَغَوْا عِلَّةً فِي الْكَوْنِ بَعْدَ انْعِدَامِهِ","فَلَمْ يَجِدُوا ذَاكُمْ فَضَلُّوا بِضَلَّةِ"],["وَإِنَّ مَبَادِي الشَّرِّ فِي كُلِّ أُمَّةٍ","ذَوِي مِلَّةٍ مَيْمُونَةٍ نَبَوِيَّةِ"],["بِخَوْضِهِمُ فِي ذَاكُمُ صَارَ شِرْكُهُمْ","وَجَاءَ دُرُوسُ الْبَيِّنَاتِ بِفَتْرَةِ"],["وَيَكْفِيكَ نَقْضًا أَنَّ مَا قَدْ سَأَلْتَهُ","مِنَ الْعُذْرِ مَرْدُودٌ لَدَى كُلِّ فِطْرَةِ"],["فَأَنْتَ تَعِيبُ الطَّاعِنِينَ جَمِيعَهُمْ","عَلَيْكَ وَتَرْمِيهِمْ بِكُلِّ مَذَمَّةِ"],["وَتَنْحَلُ مَنْ وَالَاكَ صَفْوَ مَوَدَّةٍ","وَتُبْغِضُ مَنْ نَاوَاكَ مِنْ كُلِّ فِرْقَةِ"],["وَحَالُهُمُ فِي كُلِّ قَوْلٍ وَفَعْلَةٍ","كَحَالِكَ يَا هَذَا بِأَرْجَحِ حُجَّةِ"],["وَهَبْكَ كَفَفْتَ اللَّوْمَ عَنْ كُلِّ كَافِرٍ","وَكُلِّ غَوِيٍّ خَارِجٍ عَنْ مَحَجَّةِ"],["فَيَلْزَمُكَ الْإِعْرَاضُ عَنْ كُلِّ ظَالِمٍ","عَلَى النَّاسِ فِي نَفْسٍ وَمَالٍ وَحُرْمَةِ"],["فَلَا تَغْضَبَنْ يَوْمًا عَلَى سَافِكٍ دَمًا","وَلَا سَارِقٍ مَالًا لِصَاحِبِ فَاقَةِ"],["وَلَا شَاتِمٍ عِرْضًا مَصُونًا وَإِنْ عَلَا","وَلَا نَاكِحٍ فَرْجًا عَلَى وَجْهِ غَيَّةِ"],["وَلَا قَاطِعٍ لِلنَّاسِ نَهْجَ سَبِيلِهِمْ","وَلَا مُفْسِدٍ فِي الْأَرْضِ مِنْ كُلِّ وِجْهَةِ"],["وَلَا شَاهِدٍ بِالزُّورِ إِفْكًا وَفِرْيَةً","وَلَا قَاذِفٍ لِلْمُحْصَنَاتِ بِزَنْيَةِ"],["وَلَا مُهْلِكٍ لِلْحَرْثِ وَالنَّسْلِ عَامِدًا","وَلَا حَاكِمٍ لِلْعَالَمِينَ بِرِشْوَةِ"],["وَكُفَّ لِسَانَ اللَّوْمِ عَنْ كُلِّ مُفْسِدٍ","وَلَا تَأْخُذَنْ ذَا جُرْمَةٍ بِعُقُوبَةِ"],["وَسَهِّلْ سَبِيلَ الْكَاذِبِينَ تَعَمُّدًا","عَلَى رَبِّهِمْ مِنْ كُلِّ جَاءٍ بِفِرْيَةِ"],["وَإِنْ قَصَدُوا إِضْلَالَ مَنْ يَسْتَجِيبُهُمْ","بِرَوْمِ فَسَادِ النَّوْعِ ثُمَّ الرِّيَاسَةِ"],["وَجَادِلْ عَنِ الْمَلْعُونِ فِرْعَوْنَ إِذْ طَغَى","فَأُغْرِقَ فِي الْيَمِّ انْتِقَامًا بِغَضْبَةِ"],["وَكُلِّ كَفُورٍ مُشْرِكٍ بِإِلَهِهِ","وَآخَرَ طَاغٍ كَافِرٍ بِنُبُوَّةِ"],["كَعَادٍ وَنُمْرُوذٍ وَقَوْمٍ لِصَالِحٍ","وَقَوْمٍ لِنُوحٍ ثُمَّ أَصْحَابِ الْأَيْكَةِ"],["وَخَاصِمْ لِمُوسَى ثُمَّ سَائِرِ مَنْ أَتَى","مِنَ الْأَنْبِيَاءِ مُحْيِيًا لِلشَّرِيعَةِ"],["عَلَى كَوْنِهِمْ قَدْ جَاهَدُوا النَّاسَ إِذْ بَغَوْا","وَنَالُوا مِنَ الْعَاصِي بَلِيغَ الْعُقُوبَةِ"],["وَإِلَّا فَكُلُّ الْخَلْقِ فِي كُلِّ لَفْظَةٍ","وَلَحْظَةِ عَيْنٍ أَوْ تَحَرُّكِ شَعْرَةِ"],["وَبَطْشَةِ كَفٍّ أَوْ تَخَطِّي قُدَيْمَةٍ","وَكُلِّ حَرَاكٍ بَلْ وَكُلِّ سَكِينَةِ"],["هُمُ تَحْتَ أَقْدَارِ الْإِلَهِ وَحُكْمِهِ","فَمَا أَنْتَ فِيمَا قَدْ أَتَيْتَ بِحُجَّةِ"],["وَهَبْكَ رَفَعْتَ اللَّوْمَ عَنْ كُلِّ فَاعِلٍ","فَعَالَ رَدًى طَرْدًا لِهَذِي الْمَقِيسَةِ"],["فَهَلْ يُمْكِنَنْ رَفْعُ الْمَلَامِ جَمِيعِهِ","عَنِ النَّاسِ طُرًّا عِنْدَ كُلِّ قَبِيحَةِ"],["وَتَرْكُ عُقُوبَاتِ الَّذِينَ قَدِ اعْتَدَوْا","وَتَرْكُ الْوَرَى الْإِنْصَافَ بَيْنَ الرَّعِيَّةِ"],["فَلَا تُضْمَنَنْ نَفْسٌ وَمَالٌ بِمِثْلِهِ","وَلَا يُعْقَبَنْ عَادٍ بِمِثْلِ الْجَرِيمَةِ"],["وَهَلْ فِي عُقُولِ النَّاسِ أَوْ فِي طِبَاعِهِمْ","قَبُولٌ لِقَوْلِ النَّذْلِ مَا وَجْهُ حِيلَتِي"],["وَيَكْفِيكَ نَقْضًا مَا بِجِسْمِ ابْنِ آدَمٍ","صَبِيٍّ وَمَجْنُونٍ وَكُلِّ بَهِيمَةِ"],["مِنَ الْأَلَمِ الْمَقْضِيِّ مِنْ غَيْرِ حِيلَةٍ","وَفِيمَا يَشَاءُ اللَّهُ أَكْمَلُ حِكْمَةِ"],["إِذَا كَانَ فِي هَذَا لَهُ حِكْمَةٌ فَمَا","يُظَنُّ بِخَلْقِ الْفِعْلِ ثُمَّ الْعُقُوبَةِ"],["فَكَيْفَ وَمِنْ هَذَا عَذَابٌ مُوَلَّدٌ","عَنِ الْفِعْلِ فِعْلِ الْعَبْدِ عِنْدَ الطَّبِيعَةِ"],["كَآكِلِ سَمٍّ أَوْجَبَ الْمَوْتَ أَكْلُهُ","وَكُلٌّ بِتَقْدِيرٍ لِرَبِّ الْبَرِيَّةِ"],["فَكُفْرُكَ يَا هَذَا كَسَمٍّ أَكَلْتَهُ","وَتَعْذِيبُ نَارٍ مِثْلُ جَرْعَةِ غُصَّةِ"],["أَلَسْتَ تَرَى فِي هَذِهِ الدَّارِ مَنْ جَنَى","يُعَاقَبُ إِمَّا بِالْقَضَا أَوْ بِشِرْعَةِ"],["وَلَا عُذْرَ لِلْجَانِي بِتَقْدِيرِ خَالِقٍ","كَذَلِكَ فِي الْأُخْرَى بِلَا مَثْنَوِيَّةِ"],["وَتَقْدِيرُ رَبِّ الْخَلْقِ لِلذَّنْبِ مُوجِبٌ","لِتَقْدِيرِ عُقْبَى الذَّنْبِ إِلَّا بِتَوْبَةِ"],["وَمَا كَانَ مِنْ جِنْسِ الْمَتَابِ لِرَفْعِهِ","عَوَاقِبَ أَفْعَالِ الْعِبَادِ الْخَبِيثَةِ"],["كَخَيْرٍ بِهِ تُمْحَى الذُّنُوبُ وَدَعْوَةٍ","تُجَابُ مِنَ الْجَانِي وَرُبَّ شَفَاعَةِ"],["وَقَوْلُ حَلِيفِ الشَّرِّ إِنِّي مُقَدَّرٌ","عَلَيَّ كَقَوْلِ الذِّئْبِ هَذِي طَبِيعَتِي"],["وَتَقْدِيرُهُ لِلْفِعْلِ يَجْلِبُ نِقْمَةً","كَتَقْدِيرِهِ الْأَشْيَاءَ طُرًّا بِعِلَّةِ"],["فَهَلْ يَنْفَعَنْ عُذْرُ الْمَلُومِ بِأَنَّهُ","كَذَا طَبْعُهُ أَمْ هَلْ يُقَالُ لِعَثْرَةِ"],["أَمِ الذَّمُّ وَالتَّعْذِيبُ أَوْكَدُ لِلَّذِي","طَبِيعَتُهُ فِعْلُ الشُّرُورِ الشَّنِيعَةِ"],["فَإِنْ كُنْتَ تَرْجُو أَنْ تُجَابَ بِمَا عَسَى","يُنَجِّيكَ مِنْ نَارِ الْإِلَهِ الْعَظِيمَةِ"],["فَدُونَكَ رَبَّ الْخَلْقِ فَاقْصِدْهُ ضَارِعًا","مُرِيدًا لِأَنْ يَهْدِيكَ نَحْوَ الْحَقِيقَةِ"],["وَذَلِّلْ قِيَادَ النَّفْسِ لِلْحَقِّ وَاسْمَعَنْ","وَلَا تُعْرِضَنْ عَنْ فِكْرَةٍ مُسْتَقِيمَةِ"],["وَمَا بَانَ مِنْ حَقٍّ فَلَا تَتْرُكَنَّهُ","وَلَا تَعْصِ مَنْ يَدْعُو لِأَقْوَمِ شِرْعَةِ"],["وَدَعْ دِينَ ذِي الْعَادَاتِ لَا تَتْبَعَنَّهُ","وَعُجْ عَنْ سَبِيلِ الْأُمَّةِ الْغَضَبِيَّةِ"],["وَمَنْ ضَلَّ عَنْ حَقٍّ فَلَا تَقْفُوَنَّهُ","وَزِنْ مَا عَلَيْهِ النَّاسُ بِالْمَعْدِلِيَّةِ"],["هُنَالِكَ تَبْدُو طَالِعَاتٌ مِنَ الْهُدَى","بِتَبْشِيرِ مَنْ قَدْ جَاءَ بِالْحَنَفِيَّةِ"],["بِمِلَّةِ إِبْرَاهِيمَ ذَاكَ إِمَامُنَا","وَدِينِ رَسُولِ اللَّهِ خَيْرِ الْبَرِيَّةِ"],["فَلَا يَقْبَلُ الرَّحْمَنُ دِينًا سِوَى الَّذِي","بِهِ جَاءَتِ الرُّسْلُ الْكِرَامُ السَّجِيَّةِ"],["وَقَدْ جَاءَ هَذَا الْحَاشِرُ الْخَاتَمُ الَّذِي","حَوَى كُلَّ خَيْرٍ فِي عُمُومِ الرِّسَالَةِ"],["وَأَخْبَرَ عَنْ رَبِّ الْعِبَادِ بِأَنَّ مَنْ","غَدَا عَنْهُ فِي الْأُخْرَى بِأَقْبَحِ خَيْبَةِ"],["فَهَذِي دَلَالَاتُ الْعِبَادِ لِحَائِرٍ","وَأَمَّا هُدَاهُ فَهْوَ فِعْلُ الرُّبُوبَةِ"],["وَفَقْدُ الْهُدَى عِنْدَ الْوَرَى لَا يُفِيدُ مَنْ","غَدَا عَنْهُ بَلْ يَجْرِي بِلَا وَجْهِ حُجَّةِ"],["وَحُجَّةُ مُحْتَجٍّ بِتَقْدِيرِ رَبِّهِ","تَزِيدُ عَذَابًا كَاحْتِجَاجِ مَرِيضَةِ"],["وَأَمَّا رِضَانَا بِالْقَضَاءِ فَإِنَّمَا","أُمِرْنَا بِأَنْ نَرْضَى بِمِثْلِ الْمُصِيبَةِ"],["كَسُقْمٍ وَفَقْرٍ ثُمَّ ذُلٍّ وَغُرْبَةٍ","وَمَا كَانَ مِنْ مُؤْذٍ بِدُونِ جَرِيمَةِ"],["فَأَمَّا الْأَفَاعِيلُ الَّتِي كُرِهَتْ لَنَا","فَلَا نَصَّ يَأْتِي فِي رِضَاهَا بِطَاعَةِ"],["وَقَدْ قَالَ قَوْمٌ مِنْ أُولِي الْعِلْمِ لَا رِضًا","بِفِعْلِ الْمَعَاصِي وَالذُّنُوبِ الْكَبِيرَةِ"],["فَإِنَّ إِلَهَ الْخَلْقِ لَمْ يَرْضَهَا لَنَا","فَلَا نَرْتَضِي مَسْخُوطَةً لِمَشِيئَةِ"],["وَقَالَ فَرِيقٌ نَرْتَضِي بِقَضَائِهِ","وَلَا نَرْتَضِي الْمَقْضِيَّ أَقْبَحَ خَصْلَةِ"],["وَقَالَ فَرِيقٌ نَرْتَضِي بِإِضَافَةٍ","إِلَيْهِ وَمَا فِينَا فَنَلْقَى بِسَخْطَةِ"],["كَمَا أَنَّهَا لِلرَّبِّ خَلْقٌ وَأَنَّهَا","لِمَخْلُوقِهِ كَسْبٌ كَفِعْلِ الْغَرِيزَةِ"],["فَنَرْضَى مِنَ الْوَجْهِ الَّذِي هُوَ خَلْقُهُ","وَنَسْخَطُ مِنْ وَجْهِ اكْتِسَابِ الْخَطِيئَةِ"],["وَمَعْصِيَةُ الْعَبْدِ الْمُكَلَّفِ تَرْكُهُ","لِمَا أَمَرَ الْمَوْلَى وَإِنْ بِمَشِيئَةِ"],["فَإِنَّ إِلَهَ الْخَلْقِ حَقَّ مَقَالُهُ","بِأَنَّ عِبَادِي فِي جَحِيمٍ وَجَنَّةِ"],["كَمَا أَنَّهُمْ فِي هَذِهِ الدَّارِ هَكَذَا","بَلِ الْبُهْمُ فِي الْآلَامِ أَيْضًا وَنِعْمَةِ"],["وَحِكْمَتُهُ الْعُلْيَا اقْتَضَتْ مَا اقْتَضَتْ مِنَ الْـ","ـفُرُوقِ بِعِلْمٍ ثُمَّ أَيْدٍ وَرَحْمَةِ"],["يَسُوقُ أُولِي التَّعْذِيبِ بِالسَّبَبِ الَّذِي","يُقَدِّرُهُ نَحْوَ الْعَذَابِ بِعِزَّةِ"],["وَيَهْدِي أُولِي التَّنْعِيمِ نَحْوَ نَعِيمِهِمْ","بِأَعْمَالِ صِدْقٍ فِي رَجَاءٍ وَخَشْيَةِ"],["وَأَمْرُ إِلَهِ الْخَلْقِ بَيَّنَ مَا بِهِ","يَسُوقُ أُولِي التَّنْعِيمِ نَحْوَ السَّعَادَةِ"],["فَمَنْ كَانَ مِنْ أَهْلِ السَّعَادَةِ أَثَّرَتْ","أَوَامِرُهُ فِيهِ بِتَيْسِيرِ صَنْعَةِ"],["وَمَنْ كَانَ مِنْ أَهْلِ الشَّقَاوَةِ لَمْ يُبَلْ","بِأَمْرٍ وَلَا نَهْيٍ بِتَيْسِيرِ شِقْوَةِ"],["وَلَا مَخْرَجٌ لِلْعَبْدِ عَمَّا بِهِ قَضَى","وَلَكِنَّهُ مُخْتَارُ حُسْنٍ وَسَوْأَةِ"],["فَلَيْسَ بِمَجْبُورٍ عَدِيمٍ إِرَادَةً","وَلَكِنَّهُ شَاءٍ بِخَلْقِ الْإِرَادَةِ"],["وَمِنْ أَعْجَبِ الْأَشْيَاءِ خَلْقُ مَشِيئَةٍ","بِهَا صَارَ مُخْتَارَ الْهُدَى وَالضَّلَالَةِ"],["فَقَوْلُكَ هَلْ أَخْتَارُ تَرْكًا لِحُكْمِهِ","كَقَوْلِكَ هَلْ أَخْتَارُ تَرْكَ الْمَشِيئَةِ"],["وَأَخْتَارُ لَا أَخْتَارُ فِعْلَ ضَلَالَةٍ","وَلَوْ نِلْتَ هَذَا التَّرْكَ فُزْتَ بِتَوْبَةِ"],["وَذَا مُمْكِنٌ لَكِنَّهُ مُتَوَقِّفٌ","عَلَى مَا يَشَاءُ اللَّهُ مِنْ ذِي الْمَشِيئَةِ"],["فَدُونَكَ فَافْهَمْ مَا بِهِ قَدْ أُجِبْتَ مِنْ","مَعَانٍ إِذَا انْحَلَّتْ بِفَهْمِ غَرِيزَةِ"],["أَشَارَتْ إِلَى أَصْلٍ يُشِيرُ إِلَى الْهُدَى","وَلِلَّهِ رَبِّ الْخَلْقِ أَكْمَلُ مِدْحَةِ"],["وَصَلَّى إِلَهُ الْخَلْقِ جَلَّ جَلَالُهُ","عَلَى الْمُصْطَفَى الْمُخْتَارِ خَيْرِ الْبَرِيَّةِ"]],"secs":{"1":"سؤال الذمي","9":"جواب شيخ الإسلام ابن تيمية"}}],"sharh":false};
